const raw = $input.first().json;
let parsed;
try {
  parsed = typeof raw.listings === 'string' ? JSON.parse(raw.listings) : raw;
} catch (_) { parsed = raw; }

const listings = parsed.listings || (Array.isArray(parsed) ? parsed : [parsed]);
return listings.map(l => ({ json: l }));

